const PROTECTED=['saved','chatinfo','chatopts','user','notifications','blocked','region','privacy','terms','safety','rate','deactivate','editprofile','avatar','mine','addpet','edit','messages','chat','profile','contact','contactf'];
async function route(){const tok=++routeTok;closeGate();const h=location.hash.replace(/^#\/?/,'');const [r,a]=h.split('/');
if(PROTECTED.includes(r)&&!S.user){tmp.next='#/'+h;r!=='login'&&(location.hash='#/login');return}
let html;try{switch(r){case '':html=await vList();break;case 'pet':html=await vPet(a);break;case 'contact':html=await vContact(a);break;case 'notifications':html=await vNotifs();break;case 'blocked':html=await vBlocked();break;case 'region':html=await vRegion();break;case 'privacy':html=await vPrivacy();break;case 'terms':html=await vTerms();break;case 'safety':html=await vSafety();break;case 'rate':html=await vRate();break;case 'deactivate':html=await vDeact();break;case 'user':html=await vUser(a);break;case 'saved':html=await vSaved();break;case 'chatinfo':html=await vChatInfo(a);break;case 'chatopts':html=await vChatOpts(a);break;case 'editprofile':html=await vEditProfile();break;case 'avatar':html=await vAvatar();break;case 'fpet':html=await vFpet(a);break;case 'contactf':html=await vContactF(a);break;case 'found':html=await vFound();break;case 'results':html=await vResults();break;case 'login':html=S.user?await vProfile():await vLogin();break;case 'reset':html=await vReset();break;case 'mine':html=await vMine();break;case 'addpet':html=await vAdd();break;case 'edit':html=await vAdd(a);break;case 'messages':html=await vMsgs(a);break;case 'chat':html=await vChat(a);break;case 'profile':html=await vProfile();break;default:html=head(t('notFound'),'','#/')}}
catch(e){html=head(t('appname'),'','#/')+`<div class="pad"><div class="info warn">${esc(errMsg(e))}</div></div>`}
if(tok!==routeTok)return;document.documentElement.lang=S.lang;$('#app').innerHTML=html;if(r==='addpet'||r==='edit')initBreed();nav(r==='login'&&S.user?'profile':r);if(r==='')fillList();window.scrollTo(0,0);document.body.classList.toggle('inchat',r==='chat');const m=$('#msgs');if(m)m.scrollTop=m.scrollHeight}
async function rerender(keep){const y=window.scrollY;await route();if(keep)window.scrollTo(0,y)}
