function shrink(file){return new Promise((ok,no)=>{if(!file.type.startsWith('image/')||file.size>5*1024*1024)return no();const url=URL.createObjectURL(file);const im=new Image();im.onload=()=>{const m=1024,k=Math.min(1,m/Math.max(im.width,im.height));const c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);URL.revokeObjectURL(url);c.toBlob(b=>b?ok({blob:b,url:URL.createObjectURL(b)}):no(),'image/jpeg',.82)};im.onerror=()=>{URL.revokeObjectURL(url);no()};im.src=url})}
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='rc'||el.id==='hc'){const f=$('#'+el.id+'-flag');if(f)f.textContent=flag(el.value);return}
if(el.id==='bc'){S.country=el.value;S.countryTouched=true;try{localStorage.setItem('dh-country',el.value)}catch(e){}rerender(true);return}
if(el.id==='asp'){tmp.bs={mixed:false,list:[]};renderBreed();return}if(!el.dataset||!el.dataset.file)return;const list=el.dataset.file==='found'?tmp.foundPhotos:el.dataset.file==='contact'?tmp.contactPhotos:tmp.petPhotos;saveFields();for(const f of el.files){if(el.dataset.file==='contact'&&list.length>=5){toast(t('maxPhotos'));break}try{list.push(await shrink(f))}catch(x){toast(t('badFile'))}}rerender(true)});
function saveFields(){const v=id=>{const e=document.getElementById(id);return e?e.value:undefined};if(location.hash.startsWith('#/addpet')&&$('#an')){tmp.petForm={name:v('an'),species:v('asp'),breed:buildBreed(),color:buildColor(),sex:v('ase'),age:v('aa'),marks:v('am'),desc:v('ad'),chip:v('ach')}};if(location.hash.startsWith('#/found')){tmp.find=tmp.find||{species:'',place:'',desc:''};if(v('fplace')!==undefined)tmp.find.place=v('fplace');if(v('fdesc')!==undefined)tmp.find.desc=v('fdesc')}}
const streetOf=a=>a.road?a.road+(a.house_number?' '+a.house_number:''):(a.pedestrian||a.footway||a.path||a.square||'');
const areaOf=a=>a.suburb||a.neighbourhood||a.quarter||a.city_district||a.village||a.town||a.city||a.municipality||'';
const cityOf=a=>a.city||a.town||a.municipality||a.village||a.county||'';
function mkPlace(a){const street=streetOf(a),area=areaOf(a),city=cityOf(a)||area;const parts=[street,area&&area!==street&&area!==city?area:''].filter(Boolean);const place=(parts.join(', ')||area||city).slice(0,110);return{place,city:city||place,area:area||city,country:String(a.country_code||'').toUpperCase(),label:place===city?place:place+', '+city}}
async function reverseAddr(lat,lon){const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&zoom=18&addressdetails=1&accept-language=${S.lang}&lat=${lat}&lon=${lon}`);if(!r.ok)throw 0;const j=await r.json();if(!j.address)throw 0;return mkPlace(j.address)}
async function reverseGeo(lat,lon){const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&zoom=14&accept-language=${S.lang}&lat=${lat}&lon=${lon}`);if(!r.ok)throw 0;const a=(await r.json()).address||{};const area=a.suburb||a.neighbourhood||a.quarter||a.village||a.town||a.city||'';const city=a.city||a.town||a.municipality||a.village||'';return[area,city]}
